window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[172]={"id":"172","numero":172,"titre":"Parasitoses digestives","objectifs":[{"id":"172-1","rang":"A","rubrique":"Définition","titre":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">parasitoses digestives</span> regroupent les infections du tube digestif dues à des <strong><span class=\"kw-etio\">protozoaires</span></strong> (parasites unicellulaires) ou à des <strong><span class=\"kw-etio\">helminthes</span></strong> (vers). Elles sont essentiellement liées au <strong><span class=\"kw-def\">péril fécal</span></strong>. La fiche source en retient <strong><span class=\"kw-chiffre\">7 principales</span></strong> responsables d'atteinte intestinale.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Agent pathogène</th><th>Groupe</th><th>Transmission en France</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span class=\"kw-etio\">Giardia duodenalis</span></td><td><span class=\"kw-etio\">Protozoaire</span></td><td><strong>Oui</strong> (cosmopolite)</td></tr>\n          <tr><td><strong>Amœbose</strong></td><td><span class=\"kw-etio\">Entamoeba histolytica</span></td><td><span class=\"kw-etio\">Protozoaire</span></td><td>Le plus souvent importée</td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td><span class=\"kw-etio\">Cryptosporidium parvum</span></td><td><span class=\"kw-etio\">Protozoaire</span></td><td>Cosmopolite, surtout tropicale</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span class=\"kw-etio\">Taenia saginata</span><br><span class=\"kw-etio\">Taenia solium</span></td><td><span class=\"kw-etio\">Helminthe — cestode</span></td><td><strong>Oui</strong> pour <span class=\"kw-etio\">T. saginata</span> ; <span class=\"kw-etio\">T. solium</span> importé</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td><span class=\"kw-etio\">Enterobius vermicularis</span></td><td><span class=\"kw-etio\">Helminthe — nématode</span></td><td><strong>Oui</strong> (cosmopolite)</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td><span class=\"kw-etio\">Ascaris lumbricoides</span></td><td><span class=\"kw-etio\">Helminthe — nématode</span></td><td>Exceptionnelle (importée)</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td><span class=\"kw-etio\">Strongyloides stercoralis</span></td><td><span class=\"kw-etio\">Helminthe — nématode</span></td><td>Importée (zones tropicales)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Rappel — <span class=\"kw-def\">classification</span> des parasites pathogènes pour l'homme.</strong> Le grand discriminant <span class=\"kw-ttt\">biologique</span> est l'<span class=\"kw-bio\">hyperéosinophilie</span> : <strong>absente</strong> dans <span class=\"kw-clinique\">les</span> parasitoses à protozoaires, <strong>possible</strong> dans les helminthiases.</p>\n      <table >\n        <thead><tr><th>Embranchement</th><th>Sous-groupe</th><th>Exemples digestifs</th><th>Hyperéosinophilie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Protozoaires</strong><br>(parasites unicellulaires)</td><td>—</td><td><span class=\"kw-etio\">Entamoeba histolytica</span>, <span class=\"kw-etio\">Giardia duodenalis</span>, <span class=\"kw-etio\">Cryptosporidium parvum</span></td><td><span class=\"kw-bio\">Absente</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — plathelminthes<br>(vers plats)</td><td><span class=\"kw-etio\">Cestodes</span> (segmentés)</td><td><span class=\"kw-etio\">Taenia saginata</span>, <span class=\"kw-etio\">Taenia solium</span></td><td><span class=\"kw-bio\">Possible</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — plathelminthes<br>(vers plats)</td><td><span class=\"kw-etio\">Trématodes</span> (non segmentés)</td><td><span class=\"kw-etio\">Douves</span> (distomatose), <span class=\"kw-etio\">bilharzies</span></td><td><span class=\"kw-bio\">Possible</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — némathelminthes<br>(vers ronds)</td><td><span class=\"kw-etio\">Nématodes</span></td><td><span class=\"kw-etio\">Enterobius vermicularis</span>, <span class=\"kw-etio\">Ascaris lumbricoides</span>, <span class=\"kw-etio\">Strongyloides stercoralis</span></td><td><span class=\"kw-bio\">Possible</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Seules <strong>Taenia saginata</strong>, l'<strong>oxyurose</strong> et la <strong>giardiose</strong> se transmettent couramment en France métropolitaine. <span class=\"kw-clinique\">Les</span> autres parasitoses intestinales sont le plus souvent <strong>importées</strong> (voyageurs, migrants).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"172-2","rang":"A","rubrique":"Définition","titre":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","contenu":"<p>Deux parasitoses peuvent toucher le <span class=\"kw-def\">foie</span>. La fiche source en développe une de façon complète.</p>\n      <p><strong>1 — Amœbose hépatique</strong> (<span class=\"kw-clinique\">abcès</span> amibien du foie). Agent : <strong><span class=\"kw-etio\">Entamoeba histolytica</span></strong> (<span class=\"kw-etio\">protozoaire</span>). Elle <strong>succède toujours à une atteinte intestinale</strong> et résulte d'une dissémination des <span class=\"kw-etio\">trophozoïtes</span> par voie sanguine (veine porte) vers le foie. Tableau : <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">douleur de l'hypochondre droit</span>, <span class=\"kw-clinique\">hépatomégalie douloureuse</span> (détaillé dans l'objectif « manifestations cliniques de l'amœbose »).</p>\n      <p>En France, l'amœbose est une <strong>pathologie du voyageur ou du migrant</strong> ; c'est une maladie presque cosmopolite (l'une des parasitoses <span class=\"kw-clinique\">les</span> plus fréquentes avec le <span class=\"kw-clinique\">paludisme</span> et la bilharziose). <strong>Aucun facteur climatique</strong> n'intervient dans sa <span class=\"kw-imagerie\">diffusion</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/172/carte-repartition-amoebose-monde.png\" alt=\"Carte du monde montrant la répartition géographique de l'amœbose : zones d'endémie réparties sur la ceinture intertropicale (Afrique, Amérique centrale et du Sud, Asie du Sud-Est)\" loading=\"lazy\">\n        <figcaption>Répartition géographique de l'amœbose dans le Monde : pays d'endémie répartis sur la ceinture intertropicale. Source : ANOFEL, fiche source EDN item 172.</figcaption>\n      </figure>\n      <p><strong>2 — Échinococcose hydatique</strong> (hydatidose hépatique). La fiche source la cite comme <span class=\"kw-def\">diagnostic différentiel</span> de l'<span class=\"kw-clinique\">abcès</span> amibien : elle est due à un <strong>tænia du <span class=\"kw-etio\">chien</span></strong> (<span class=\"kw-etio\">Echinococcus granulosus</span>), en <strong>impasse <span class=\"kw-etio\">parasitaire</span> chez l'homme</strong>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> deux parasitoses hépatiques à connaître sont l'<strong>amœbose hépatique</strong> (<span class=\"kw-etio\">Entamoeba histolytica</span>) et l'<strong>échinococcose hydatique</strong> (<span class=\"kw-etio\">Echinococcus granulosus</span>). La fiche source du dossier <code>172-parasitoses-disgestives/</code> développe uniquement l'amœbose hépatique ; l'hydatidose n'y est mentionnée que comme <span class=\"kw-def\">diagnostic différentiel</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 173 — Zoonose</em></p>","frequence":0},{"id":"172-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modes de transmission des parasitoses digestives","contenu":"<p><span class=\"kw-clinique\">Les</span> parasitoses digestives sont <strong>essentiellement liées au <span class=\"kw-def\">péril fécal</span></strong> (transmission <strong>féco-orale</strong>). <strong>Aucun vaccin</strong> n'est disponible ; la prévention repose sur le renforcement des mesures d'<span class=\"kw-clinique\">hygiène individuelle et collective</span>.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Mode de transmission</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td>Indirecte (<span class=\"kw-clinique\">eau, aliments</span>) ; directe (mains souillées) ; <strong>transmission interhumaine</strong> et horizontale</td></tr>\n          <tr><td><strong>Amœbose</strong></td><td>Voie <span class=\"kw-clinique\">orofécale</span> (eau, aliments) ou <strong>manuportage</strong> — formes kystiques présentes dans le milieu extérieur</td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td>Indirecte (<span class=\"kw-clinique\">eau, aliments</span>) ; directe (mains souillées)</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td>Ingestion de <strong>viande parasitée mal cuite ou crue</strong> : bœuf pour <span class=\"kw-etio\">T. saginata</span>, porc pour <span class=\"kw-etio\">T. solium</span></td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td>Ingestion d'œufs (mains, sous-vêtements, literie) ; <strong>auto-infestation</strong> orale fréquente après grattage anal</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>Ingestion d'œufs présents dans l'eau ou <span class=\"kw-clinique\">les</span> aliments souillés (<span class=\"kw-def\">péril fécal</span> humain)</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td><strong>Pénétration transcutanée des larves</strong> — marche pieds nus sur une terre humide</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> L'<strong>anguillulose</strong> est la seule parasitose digestive de cette liste à ne <strong>pas</strong> suivre la voie féco-orale : sa contamination est <strong>transcutanée</strong>. Le taeniasis se distingue aussi : transmission par la <strong>viande</strong>, pas directement par <span class=\"kw-clinique\">les</span> selles.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical · 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse</em></p>","frequence":0},{"id":"172-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","contenu":"<p>Présentation clinique des <strong>6 parasitoses intestinales hors amœbose</strong>. Trait commun : elles sont <strong>souvent asymptomatiques</strong>, le portage chronique est fréquent.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td>\n            Souvent <span class=\"kw-clinique\">asymptomatique</span><br>\n            <strong>Dyspepsie :</strong> <span class=\"kw-clinique\">douleurs épigastriques</span> ; <span class=\"kw-clinique\">nausées</span> ; <span class=\"kw-clinique\">ballonnement post-prandial</span><br>\n            <strong><span class=\"kw-clinique\">Diarrhée</span> :</strong> chronique, fluctuante, <strong>sans glaire ni sang</strong> ; <span class=\"kw-clinique\">selles malodorantes et décolorées</span><br>\n            <strong><span class=\"kw-def\">Terrain</span> et risque :</strong> enfant, immunodéprimé ; <span class=\"kw-alerte\">malabsorption</span> (parasitose la plus associée à la malnutrition infantile dans <span class=\"kw-clinique\">les</span> PVD)<br>\n            <strong><span class=\"kw-clinique\">Fièvre</span> :</strong> absente\n          </td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td>\n            <span class=\"kw-clinique\">Asymptomatique</span> le plus souvent<br>\n            <strong>Digestif :</strong> <span class=\"kw-clinique\">douleurs abdominales</span> ; <span class=\"kw-clinique\">nausées</span> ; <span class=\"kw-clinique\">troubles de l'appétit</span> (non spécifiques)<br>\n            <strong>Cutané :</strong> <span class=\"kw-clinique\">urticaire</span><br>\n            <strong>Signe d'appel :</strong> émission d'<strong><span class=\"kw-clinique\">anneaux</span></strong> dans <span class=\"kw-clinique\">les</span> selles, les sous-vêtements, la literie\n          </td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td>\n            <span class=\"kw-clinique\">Asymptomatique</span> le plus souvent<br>\n            <strong><span class=\"kw-clinique\">Prurit anal vespéral</span></strong> — au coucher, lié à la ponte du ver femelle<br>\n            <strong>Fille :</strong> <span class=\"kw-clinique\">vulvo-vaginite</span><br>\n            <strong>Comportement :</strong> <span class=\"kw-clinique\">irritabilité</span> ; <span class=\"kw-clinique\">troubles de la concentration</span> ; <span class=\"kw-clinique\">troubles du sommeil</span> — <strong>parfois seule manifestation</strong>\n          </td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>\n            <strong>Phase d'invasion :</strong> <span class=\"kw-clinique\">asymptomatique</span> ; <span class=\"kw-clinique\">urticaire</span> ; parfois <span class=\"kw-alerte\">syndrome de Löffler</span><br>\n            <strong>Phase d'état :</strong> <span class=\"kw-clinique\">asymptomatique</span> ou <span class=\"kw-clinique\">troubles digestifs</span> non spécifiques (dyspepsie, <span class=\"kw-clinique\">nausées</span>)<br>\n            <strong>Particularité :</strong> <span class=\"kw-clinique\">les</span> vers adultes peuvent être excrétés par les <strong><span class=\"kw-clinique\">vomissements</span></strong>\n          </td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td>\n            <span class=\"kw-clinique\">Asymptomatique</span> le plus souvent<br>\n            <span class=\"kw-clinique\">Larva currens</span> cutanée ; <span class=\"kw-clinique\">troubles digestifs</span> ; <span class=\"kw-alerte\">syndrome de Löffler</span><br>\n            <em>Circonstances détaillées dans l'objectif dédié à l'anguillulose</em>\n          </td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td>\n            <span class=\"kw-clinique\">Diarrhée aiguë cholériforme</span> ou <span class=\"kw-clinique\">diarrhée chronique</span><br>\n            <em>Circonstances détaillées dans l'objectif dédié à la cryptosporidiose</em>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe EDN.</strong> Devant une <strong><span class=\"kw-clinique\">diarrhée</span> chronique au retour de voyage</strong>, surtout chez l'enfant, penser à la <strong>giardiose</strong> — selles décolorées et malodorantes, sans sang.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie · 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse</em></p>","frequence":2},{"id":"172-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une anguillulose","contenu":"<p>Agent : <strong><span class=\"kw-etio\">Strongyloides stercoralis</span></strong> (<span class=\"kw-etio\">nématode</span>). Géographie : présente dans <strong>tous <span class=\"kw-clinique\">les</span> pays tropicaux</strong>.</p>\n      <p><strong>Circonstances évocatrices</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Épidémiologie</span> :</strong> séjour en <span class=\"kw-clinique\">zone tropicale</span> ; transmission par <strong>pénétration transcutanée des larves</strong> (marche pieds nus sur une terre humide).</li>\n        <li><strong>Clinique :</strong> <span class=\"kw-clinique\">asymptomatique</span> le plus souvent ; <strong><span class=\"kw-clinique\">syndrome de larva currens cutanée</span></strong> (<span class=\"kw-clinique\">urticaire</span> + dermatite rampante) ; <span class=\"kw-clinique\">troubles digestifs</span> (douleurs ép<span class=\"kw-chiffre\">iga</span>striques, <span class=\"kw-clinique\">diarrhée</span>) ; <span class=\"kw-alerte\">syndrome de Löffler</span> plus rarement.</li>\n        <li><strong>Biologie :</strong> <strong><span class=\"kw-bio\">hyperéosinophilie oscillante ou cyclique</span></strong> (inconstante) — liée au cycle d'auto-infestation digestive.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Forme grave — anguillulose maligne.</strong> Chez l'<strong>immunodéprimé</strong>, l'auto-infestation s'emballe : forme disséminée souvent <strong>mortelle</strong> — <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">purpura péri-ombilical</span>.</div>\n      <div class=\"callout callout-warn\"><strong>Point EDN majeur.</strong> Dépister et traiter l'anguillulose <strong>avant toute immunosuppression</strong> (<span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">chimiothérapie</span>) chez tout patient ayant séjourné en zone d'endémie — <strong>y compris en l'absence de documentation</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie · 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"172-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une cryptosporidiose","contenu":"<p>Agent : <strong><span class=\"kw-etio\">Cryptosporidium parvum</span></strong> (protozoaire). Géographie : cosmopolite, plus fréquente dans <span class=\"kw-clinique\">les</span> régions tropicales.</p>\n      <ul>\n        <li><strong>Transmission :</strong> indirecte (<span class=\"kw-clinique\">eau, aliments</span>) ou directe (mains souillées).</li>\n        <li><strong>Clinique :</strong> soit <span class=\"kw-clinique\">diarrhée aiguë cholériforme</span>, soit <span class=\"kw-clinique\">diarrhée chronique</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Circonstance clé.</strong> Chez l'<strong>immunodéprimé</strong> (<span class=\"kw-etio\">VIH</span> notamment), la cryptosporidiose donne des formes <strong>sévères et prolongées</strong> : <span class=\"kw-alerte\">malabsorption</span>, <span class=\"kw-alerte\">angiocholites</span>. Toute <span class=\"kw-clinique\">diarrhée</span> chronique sur <span class=\"kw-def\">terrain</span> immunodéprimé doit la faire évoquer.</div>","frequence":0},{"id":"172-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","contenu":"<p>L'amœbose à <span class=\"kw-etio\">Entamoeba histolytica</span> donne deux tableaux distincts, à bien différencier — notamment sur le critère <strong><span class=\"kw-clinique\">fièvre</span></strong>.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale aiguë</strong></td><td>\n            <strong>Forme aiguë :</strong> <span class=\"kw-clinique\">syndrome dysentérique</span> — surtout chez l'enfant en pays tropical<br>\n            <strong>Forme subaiguë :</strong> <span class=\"kw-clinique\">douleurs abdominales</span> ; <span class=\"kw-clinique\">selles molles peu nombreuses</span> ; simple perte de la selle moulée quotidienne<br>\n            <strong>Signes rectaux :</strong> <span class=\"kw-clinique\">épreintes</span> ; <span class=\"kw-clinique\">ténesme</span> ; <span class=\"kw-clinique\">toucher rectal douloureux</span><br>\n            <strong><span class=\"kw-clinique\">Fièvre</span> :</strong> <span class=\"kw-alerte\">ABSENTE</span> — signe négatif capital\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong><br>(<span class=\"kw-clinique\">abcès</span> amibien)</td><td>\n            Installation <strong>aiguë</strong><br>\n            <strong>Général :</strong> <span class=\"kw-clinique\">fièvre élevée</span> ; <span class=\"kw-clinique\">frissons</span><br>\n            <strong>Douleur :</strong> <span class=\"kw-clinique\">hypochondre droit</span>, irradiant à l'épaule droite<br>\n            <strong>Examen :</strong> <span class=\"kw-clinique\">hépatomégalie douloureuse</span> à la palpation<br>\n            <strong>Respiratoire :</strong> <span class=\"kw-clinique\">toux sèche</span> possible (irritation phrénique)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Complications de l'amœbose intestinale.</strong> <span class=\"kw-alerte\">Forme fulminante</span> — <strong>mortelle dans <span class=\"kw-chiffre\">50 %</span> des cas</strong> ; <span class=\"kw-alerte\">amœbome</span> (pseudo-tumeur de la fosse iliaque droite) ; <span class=\"kw-alerte\">colite nécrosante aiguë</span> sur <span class=\"kw-def\">terrain</span> fragile (lésions ulcérées sévères de tout le côlon).</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'amœbose <strong>hépatique</strong> peut donner des <strong>diarrhées fébriles</strong>, alors que l'amœbose <strong>intestinale aiguë n'est JAMAIS fébrile</strong>. <span class=\"kw-clinique\">Les</span> deux formes peuvent par ailleurs coexister chez un même patient.</div>","frequence":1},{"id":"172-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les complications liées à l’infestation par Tænia solium","contenu":"<p>La complication majeure de l'infestation par <span class=\"kw-etio\">Taenia solium</span> est la <strong><span class=\"kw-etio\">cysticercose</span></strong>.</p>\n      <p><strong>Mécanisme.</strong> Elle survient par <strong>ingestion directe d'œufs de <span class=\"kw-etio\">Taenia solium</span></strong> (transmission oro-fécale) : l'homme devient alors un <strong>hôte intermédiaire</strong> et héberge <span class=\"kw-clinique\">les</span> larves enkystées dans ses tissus.</p>\n      <p><strong>Localisations des kystes</strong></p>\n      <ul>\n        <li><strong>Muscles :</strong> <span class=\"kw-clinique\">œdème</span>, <span class=\"kw-clinique\">myopathie</span>.</li>\n        <li><strong>Œil :</strong> <span class=\"kw-clinique\">uvéite</span>, <span class=\"kw-alerte\">cécité</span>.</li>\n        <li><strong>Cerveau — neurocysticercose :</strong> <span class=\"kw-clinique\">céphalées</span>, <strong><span class=\"kw-alerte\">crises convulsives</span></strong>, <span class=\"kw-alerte\">HTIC</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Épidémiologie</span> :</strong> la neurocysticercose est la <strong>cause principale d'<span class=\"kw-etio\">épilepsie</span> en Amérique du Sud</strong> ; contexte de séjour en zone tropicale, parfois plusieurs années auparavant.</p>\n      <p><strong>Paraclinique :</strong> <span class=\"kw-bio\">sérologie</span> souvent négative ; <span class=\"kw-imagerie\">imagerie</span> pouvant montrer des kystes ± calcifiés.</p>\n      <p><strong>Traitement :</strong> <span class=\"kw-ttt\">corticothérapie</span> initiale, puis <span class=\"kw-ttt\">albendazole</span> per os en dose unique ou <span class=\"kw-ttt\">praziquantel</span> per os en dose unique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie</em></p>","frequence":0},{"id":"172-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les moyens diagnostiques de l’amoebose intestinale et hépatique","contenu":"<table >\n        <thead><tr><th>Forme</th><th>Moyens diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong><span class=\"kw-bio\">EPS</span> :</strong> souvent seules <span class=\"kw-clinique\">les</span> formes kystiques sont vues, <strong>indifférenciables d'<span class=\"kw-etio\">E. dispar</span></strong> (non pathogène) ; à réaliser <span class=\"kw-chiffre\">×3</span>, espacés de quelques jours, acheminement rapide au laboratoire (parasite fragile)<br>\n            <strong><span class=\"kw-bio\">PCR</span> :</strong> beaucoup plus sensible que l'<span class=\"kw-bio\">EPS</span>, se généralise<br>\n            <strong><span class=\"kw-bio\">Sérologie</span> :</strong> rarement positive (atteinte muqueuse, pas tissulaire)<br>\n            <strong><span class=\"kw-imagerie\">Endoscopie</span> :</strong> <span class=\"kw-imagerie\">rectoscopie</span> — <span class=\"kw-radio\">ulcérations en coup d'ongle</span>, <span class=\"kw-radio\">abcès « en bouton de chemise »</span> ; <span class=\"kw-imagerie\">coloscopie</span> pour le <span class=\"kw-def\">diagnostic différentiel</span> des formes chroniques résistantes\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <strong><span class=\"kw-bio\">EPS</span> :</strong> le plus souvent négatif<br>\n            <strong><span class=\"kw-bio\">Sérologie</span> anti-amibiens :</strong> fortement positive en général — mais <span class=\"kw-alerte\">faux négatif possible la 1ʳᵉ semaine</span> d'<span class=\"kw-clinique\">évolution</span><br>\n            <strong><span class=\"kw-ttt\">Ponction</span> d'une collection :</strong> si <span class=\"kw-bio\">sérologie</span> négative, risque de <span class=\"kw-alerte\">rupture</span>, doute avec un <span class=\"kw-clinique\">abcès</span> pyogène ou absence de réponse au traitement — <span class=\"kw-imagerie\">pus brun chocolat</span>, <span class=\"kw-bio\">PCR</span> sur liquide confirmant le diagnostic\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Imagerie de l'amœbose hépatique</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">RXT</span> :</strong> surélévation de la coupole droite ± comblement du cul-de-sac costo-diaphragmatique droit.</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie hépatique</span> :</strong> <strong><span class=\"kw-clinique\">abcès</span> UNIQUE souvent volumineux</strong>, plus rarement multiple.</li>\n        <li><strong><span class=\"kw-imagerie\">TDM hépatique</span> :</strong> non indispensable si l'<span class=\"kw-imagerie\">échographie</span> est contributive ; utile si <span class=\"kw-clinique\">abcès</span> du dôme hépatique (invisible en <span class=\"kw-imagerie\">échographie</span>).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/172/amoebose-hepatique-abces.png\" alt=\"Coupe TDM abdominale montrant un volumineux abcès amibien hypodense du lobe droit du foie\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Abcès</span> amibien du foie droit au <span class=\"kw-imagerie\">scanner</span> : volumineuse collection hypodense, unique. Source : fiche source EDN item 172 (ANOFEL / Pilly 2023).</figcaption>\n      </figure>","frequence":0},{"id":"172-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","contenu":"<p>L'examen de base est l'<strong><span class=\"kw-bio\">EPS</span></strong> (examen parasitologique des selles), à réaliser <span class=\"kw-chiffre\">×3 à quelques jours d'intervalle</span> avec acheminement rapide au laboratoire (parasites fragiles). Certaines recherches nécessitent une <strong>demande spécifique</strong>.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th>Confirmation diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span class=\"kw-bio\">EPS</span> (formes végétatives ou kystiques — mais <span class=\"kw-bio\">EPS</span> <strong>peu sensible</strong>) ; <span class=\"kw-bio\">PCR Giardia duodenalis</span> bien plus sensible ; <span class=\"kw-bio\">biopsies</span> jéjunales ou liquide duodénal</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span class=\"kw-bio\">EPS</span> ×3 sur <span class=\"kw-chiffre\">10 jours</span> + <strong><span class=\"kw-bio\">Scotch test</span></strong> ; œufs, anneaux ou embryophores visibles au microscope</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td><strong><span class=\"kw-bio\">Scotch test</span></strong> — cellophane adhésive appliquée le matin avant la toilette anale, puis lecture au microscope ; <span class=\"kw-bio\">EPS</span> souvent négatif ; vers adultes visibles à l'œil nu</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>Œufs à l'<span class=\"kw-bio\">EPS</span> (phase d'état) ; rejet de vers adultes ; à la phase d'invasion, <span class=\"kw-clinique\">les</span> œufs <strong>ne sont pas encore éliminés</strong> dans les selles</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td>Technique de <strong><span class=\"kw-bio\">Baermann</span></strong> (recherche des larves) + <span class=\"kw-bio\">sérologie spécifique</span> — demande spécifique</td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td><span class=\"kw-bio\">PCR spécifique</span> ou coloration de <strong><span class=\"kw-bio\">Ziehl-Nielsen</span></strong> — demande spécifique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <strong>Scotch test n'est pas spécifique de l'oxyurose</strong> : il peut aussi révéler des anneaux ou des embryophores de Tænia.</div>","frequence":0},{"id":"172-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription d’une recherche spécifique d’anguillulose","contenu":"<p>La recherche de <span class=\"kw-etio\">Strongyloides stercoralis</span> ne se fait <strong>pas</strong> sur un <span class=\"kw-bio\">EPS</span> standard — elle requiert une <strong>demande spécifique</strong> au laboratoire.</p>\n      <ul>\n        <li><strong>Recherche des larves dans <span class=\"kw-clinique\">les</span> selles :</strong> technique de <strong><span class=\"kw-bio\">Baermann</span></strong> — fait l'objet d'une <strong>prescription spécifique</strong>.</li>\n        <li><strong><span class=\"kw-bio\">Sérologie spécifique</span> :</strong> en <span class=\"kw-bio\">complément</span>.</li>\n        <li><strong><span class=\"kw-bio\">Hyperéosinophilie</span> :</strong> oscillante ou cyclique, <strong>inconstante</strong> — son absence ne permet pas d'exclure le diagnostic.</li>\n      </ul>","frequence":0},{"id":"172-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription d’une recherche spécifique de cryptosporidiose","contenu":"<p>La recherche de <span class=\"kw-etio\">Cryptosporidium parvum</span> n'est <strong>pas réalisée en routine</strong> sur un <span class=\"kw-bio\">EPS</span> standard : elle <strong>fait l'objet d'une demande spécifique</strong> au laboratoire.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">PCR spécifique</span></strong> de Cryptosporidium ; <strong>ou</strong></li>\n        <li>Recherche d'<strong><span class=\"kw-etio\">oocystes</span> dans <span class=\"kw-clinique\">les</span> selles</strong> par <strong>coloration de <span class=\"kw-bio\">Ziehl-Nielsen</span></strong>.</li>\n      </ul>","frequence":0},{"id":"172-13","rang":"A","rubrique":"Contenu multimédia","titre":"Aspect macroscopique d’un Tænia sp","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">Taenia</span> sont des <strong><span class=\"kw-etio\">cestodes</span></strong> — vers plats segmentés — pouvant atteindre <strong><span class=\"kw-chiffre\">plusieurs mètres de long</span></strong>.</p>\n      <p><strong>Aspect macroscopique.</strong> Ce sont surtout <span class=\"kw-clinique\">les</span> <strong>anneaux</strong> qui sont visibles à l'œil nu : <span class=\"kw-imagerie\">anneaux plats blanchâtres</span> retrouvés dans les selles, les sous-vêtements ou la literie, d'<strong>aspect de petites tagliatelles</strong>. Les anneaux sont émis <strong>activement par l'anus pour <span class=\"kw-etio\">T. saginata</span></strong>, passivement pour <span class=\"kw-etio\">T. solium</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Image à compléter.</strong> Aucune photographie macroscopique de Tænia n'est disponible dans le dossier source <code>172-parasitoses-disgestives/</code>. Kevin fournira l'image (anneaux dans <span class=\"kw-clinique\">les</span> selles) lors d'un B-FIX ultérieur.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/amoebic-hepatic-abscess","label":"Radiopaedia : Amoebic hepatic abscess"}]},{"id":"172-14","rang":"B","rubrique":"Contenu multimédia","titre":"Aspect macroscopique d’oxyures","contenu":"<p><span class=\"kw-etio\">Enterobius vermicularis</span> est un <strong><span class=\"kw-etio\">nématode</span></strong> — ver rond non segmenté — parasite de l'intestin.</p>\n      <p><strong>Aspect macroscopique.</strong> Petit ver <span class=\"kw-imagerie\">blanchâtre</span> mesurant environ <strong><span class=\"kw-chiffre\">1 cm de long</span></strong>. <span class=\"kw-clinique\">Les</span> <strong>vers adultes sont visibles à l'œil nu</strong>, dans les selles ou sur la <strong><span class=\"kw-clinique\">marge anale</span></strong>.</p>\n      <div class=\"callout callout-warn\"><strong>Image à compléter.</strong> Aucune photographie macroscopique d'oxyures n'est disponible dans le dossier source <code>172-parasitoses-disgestives/</code>. Kevin fournira l'image (vers sur la <span class=\"kw-clinique\">marge anale</span>) lors d'un B-FIX ultérieur.</div>","frequence":0},{"id":"172-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","contenu":"<table >\n        <thead><tr><th>Parasitose</th><th>Traitement</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">5 jours</span><br>Alternative : <span class=\"kw-ttt\">albendazole</span> <span class=\"kw-chiffre\">4 jours</span></td><td>Retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois recommandé (collectivités d'enfants) ; contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span></td><td><strong>Traitement toujours indiqué</strong> + traiter <span class=\"kw-clinique\">les</span> <strong>sujets contacts</strong> ; <strong>2ᵉ cure systématique <span class=\"kw-chiffre\">2 semaines</span> plus tard</strong> ; mesures associées (ongles courts, brossage, changement de linge)</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span class=\"kw-ttt\">Praziquantel</span> PO</td><td>Parfois en plusieurs cures</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> PO</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> L'<strong>oxyurose</strong> impose une <strong>2ᵉ cure systématique à <span class=\"kw-chiffre\">2 semaines</span></strong> (interruption du cycle d'auto-infestation) et le <strong>traitement des sujets contacts</strong>, même asymptomatiques.</div>","frequence":0},{"id":"172-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l’amoebose intestinale et hépatique","contenu":"<p>Le traitement de l'amœbose associe systématiquement <strong>deux temps</strong> : un amœbicide tissulaire, puis un amœbicide de <span class=\"kw-def\">contact</span> (action sur <span class=\"kw-clinique\">les</span> formes kystiques de la lumière digestive).</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong>1 — Amœbicide tissulaire :</strong> <span class=\"kw-ttt\">métronidazole</span> <span class=\"kw-chiffre\">7 jours</span> (inefficace sur <span class=\"kw-clinique\">les</span> formes kystiques de la lumière digestive)<br>\n            <strong>2 — Amœbicide de <span class=\"kw-def\">contact</span> :</strong> <span class=\"kw-ttt\">paromomycine</span> <span class=\"kw-chiffre\">10 jours</span> (action sur la lumière digestive)\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">10 jours</span>, puis amœbicide de <span class=\"kw-def\">contact</span> (<span class=\"kw-ttt\">paromomycine</span>) pour éviter <span class=\"kw-clinique\">les</span> rechutes<br>\n            Alternatives : <span class=\"kw-ttt\">tinidazole</span> ou <span class=\"kw-ttt\">secnidazole</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Ponction</span> de l'<span class=\"kw-clinique\">abcès</span> hépatique.</strong> <strong>Inutile dans la majorité des cas.</strong> Elle est justifiée si : <span class=\"kw-clinique\">abcès</span> volumineux (<span class=\"kw-chiffre\">&gt; 10 cm</span>), abcès hyperalgique, <span class=\"kw-alerte\">risque de rupture</span>, <span class=\"kw-clinique\">évolution</span> non favorable sous <span class=\"kw-ttt\">métronidazole</span>, ou doute avec un <span class=\"kw-def\">diagnostic différentiel</span> (abcès à pyogène, tumeur nécrosée).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Sans traitement, l'<span class=\"kw-clinique\">évolution</span> de l'amœbose hépatique est <strong>défavorable</strong>.</div>","frequence":0},{"id":"172-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le principe de la surveillance post-thérapeutique des parasitoses intestinales","contenu":"<p>Principe général : <strong>contrôle par <span class=\"kw-bio\">EPS</span> à distance du traitement</strong>, surtout en cas de persistance des symptômes.</p>\n      <table >\n        <thead><tr><th>Parasitose</th><th><span class=\"kw-def\">Surveillance</span> post-thérapeutique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td>Contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td>Vérifier l'<strong>absence d'émission d'anneaux</strong> dans <span class=\"kw-clinique\">les</span> selles pendant les <span class=\"kw-chiffre\">3 mois</span> suivants</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td>Contrôle <span class=\"kw-bio\">EPS</span> à distance</td></tr>\n          <tr><td><strong>Amœbose</strong></td><td>Contrôle par <span class=\"kw-bio\">EPS</span> à distance</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Anguillulose avant toute immunosuppression :</strong> chez tout patient ayant séjourné en <span class=\"kw-etio\">zone d’endémie</span>, dépister et traiter une <span class=\"kw-clinique\">anguillulose</span> par <span class=\"kw-ttt\">ivermectine</span> <strong>avant <span class=\"kw-ttt\">corticothérapie</span> ou <span class=\"kw-ttt\">chimiothérapie</span></strong> — y compris sans documentation — sous peine d’<span class=\"kw-alerte\">anguillulose maligne</span> disséminée mortelle.<br><strong>Amœbose intestinale :</strong> redouter la <span class=\"kw-alerte\">forme fulminante</span>, mortelle dans <span class=\"kw-chiffre\">50 %</span> des cas.<br><strong>Amœbose hépatique :</strong> <span class=\"kw-clinique\">évolution</span> <span class=\"kw-alerte\">défavorable sans traitement</span> ; sous <span class=\"kw-ttt\">métronidazole</span>, <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Anguillulose maligne</span> de l’<span class=\"kw-etio\">immunodéprimé</span> : forme disséminée souvent <strong>mortelle</strong> — <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">purpura péri-ombilical</span></li><li>Amœbose intestinale : <span class=\"kw-alerte\">forme fulminante</span> (mortelle <span class=\"kw-chiffre\">50 %</span>), <span class=\"kw-alerte\">amœbome</span> (pseudo-tumeur de la fosse iliaque droite), <span class=\"kw-alerte\">colite nécrosante aiguë</span> sur <span class=\"kw-def\">terrain</span> fragile</li><li>Amœbose hépatique : <span class=\"kw-alerte\">abcès à risque de rupture</span> (volumineux <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique) ; <span class=\"kw-alerte\">faux négatif</span> de la <span class=\"kw-bio\">sérologie</span> la <span class=\"kw-chiffre\">1ʳᵉ semaine</span></li><li>Neurocysticercose (<span class=\"kw-etio\">Taenia solium</span>) : <span class=\"kw-alerte\">crises convulsives</span>, <span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-alerte\">cécité</span> (atteinte oculaire)</li><li><span class=\"kw-alerte\">Syndrome de Löffler</span> (ascaridiose, anguillulose) : <span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-imagerie\">infiltrats pulmonaires labiles</span></li><li>Giardiose / cryptosporidiose : <span class=\"kw-alerte\">malabsorption</span> ; cryptosporidiose de l’immunodéprimé : <span class=\"kw-alerte\">angiocholites</span></li></ul>","principes":"<p><strong>Cadre :</strong> <span class=\"kw-ttt\">antiparasitaire</span> ciblé per os, le plus souvent en <span class=\"kw-clinique\">ambulatoire</span> ; renforcement des mesures d’<span class=\"kw-clinique\">hygiène</span> individuelle et collective ; <strong>aucun vaccin</strong> disponible.<br><strong>Amœbose — règle des 2 temps :</strong> amœbicide tissulaire (<span class=\"kw-ttt\">métronidazole</span>) PUIS amœbicide de <span class=\"kw-def\">contact</span> (<span class=\"kw-ttt\">paromomycine</span>) actif sur <span class=\"kw-clinique\">les</span> formes kystiques de la lumière digestive.</p><p><strong>Giardiose</strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">5 jours</span> (alternative <span class=\"kw-ttt\">albendazole</span> <span class=\"kw-chiffre\">4 jours</span>)</li><li>Retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités d’enfants)</li><li>Traiter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span> symptomatiques en collectivité</li></ul><p><strong>Oxyurose</strong></p><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> — traitement <strong>toujours indiqué</strong></li><li><strong>Traiter aussi <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span></strong> (famille, collectivité)</li><li><strong><span class=\"kw-chiffre\">2ᵉ cure</span> systématique à <span class=\"kw-chiffre\">2 semaines</span></strong></li><li>Mesures : ongles courts, brossage, changement du linge</li></ul><p><strong>Taeniasis</strong></p><ul><li><span class=\"kw-ttt\">Praziquantel</span> PO, parfois en plusieurs cures</li></ul><p><strong>Ascaridiose</strong></p><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> PO</li></ul><p><strong>Anguillulose</strong></p><ul><li><span class=\"kw-ttt\">Ivermectine</span></li><li><span class=\"kw-def\">Dépistage</span>-traitement <strong>avant toute immunosuppression</strong> si séjour en <span class=\"kw-etio\">zone d’endémie</span></li></ul><p><strong>Amœbose intestinale</strong></p><ul><li>1 — <span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">7 jours</span> (amœbicide tissulaire)</li><li>2 — <span class=\"kw-ttt\">Paromomycine</span> <span class=\"kw-chiffre\">10 jours</span> (amœbicide de <span class=\"kw-def\">contact</span>)</li></ul><p><strong>Amœbose hépatique</strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> puis <span class=\"kw-ttt\">paromomycine</span> (anti-rechute) ; alternatives <span class=\"kw-ttt\">tinidazole</span>, <span class=\"kw-ttt\">secnidazole</span></li><li><span class=\"kw-ttt\">Ponction</span> inutile en règle ; justifiée si <span class=\"kw-clinique\">abcès</span> <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique, <span class=\"kw-alerte\">à risque de rupture</span>, échec ou doute diagnostique</li></ul><p><strong>Cysticercose (T. solium)</strong></p><ul><li><span class=\"kw-ttt\">Corticothérapie</span> initiale puis <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">praziquantel</span> per os en dose unique</li></ul>","suivi":"<p><strong>Principe général :</strong> contrôle par <span class=\"kw-bio\">EPS</span> à distance du traitement, surtout en cas de persistance des symptômes.<br><strong>Giardiose :</strong> contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste ; retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités).<br><strong>Taeniasis :</strong> vérifier l’absence d’émission d’<span class=\"kw-clinique\">anneaux</span> dans <span class=\"kw-clinique\">les</span> selles pendant les <span class=\"kw-chiffre\">3 mois</span> suivants.<br><strong>Oxyurose :</strong> deuxième cure systématique à <span class=\"kw-chiffre\">2 semaines</span> + contrôle <span class=\"kw-bio\">EPS</span> à distance.<br><strong>Amœbose :</strong> contrôle <span class=\"kw-bio\">EPS</span> à distance ; sous traitement, <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>, baisse rapide de la <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-imagerie\">échographie</span> contrôlée seulement si <span class=\"kw-clinique\">évolution</span> défavorable.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf","label":"Collège Pilly — Parasitoses digestives (item 172, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Manifestation digestive ± hyperéosinophilie — Préciser le caractère des selles et le terrain","detail":"<h4>CAT — Démarche diagnostique des parasitoses digestives — Caractère des selles + <span class=\"kw-def\">terrain</span> → parasite, examen spécifique, traitement</h4>","branches":[{"to":"q-proto","label":"Pas d’hyperéosinophilie → protozoaire","color":"blue"},{"to":"q-helm","label":"Hyperéosinophilie / signes d’helminthiase","color":"blue"}]},{"id":"q-proto","kind":"decision","label":"Protozoaire — caractère des selles + terrain ?","branches":[{"to":"t-amibe-int","label":"Syndrome dysentérique SANS fièvre, pays tropical","color":"amber"},{"to":"t-amibe-hep","label":"Fièvre élevée + douleur hypochondre droit + hépatomégalie","color":"amber"},{"to":"t-giardiose","label":"Diarrhée chronique, selles décolorées sans sang","color":"green"},{"to":"t-crypto","label":"Diarrhée chez immunodéprimé (VIH)","color":"amber"}]},{"id":"t-amibe-int","kind":"terminal","label":"Amœbose intestinale aiguë","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Syndrome dysentérique</span> (forme aiguë, enfant en pays tropical)</li><li>Forme subaiguë : <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">selles molles peu nombreuses</span></li><li><span class=\"kw-clinique\">Épreintes</span>, <span class=\"kw-clinique\">ténesme</span>, <span class=\"kw-clinique\">toucher rectal douloureux</span></li><li><span class=\"kw-clinique\">Fièvre</span> ABSENTE — signe négatif capital</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> espacés de quelques jours, acheminement rapide (formes kystiques indifférenciables d’<span class=\"kw-etio\">E. dispar</span>)</li><li><span class=\"kw-bio\">PCR</span> plus sensible ; <span class=\"kw-bio\">sérologie</span> rarement positive</li></ul><h4>Traitement</h4><ul><li>1 — <span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">7 jours</span> (amœbicide tissulaire)</li><li>2 — <span class=\"kw-ttt\">Paromomycine</span> <span class=\"kw-chiffre\">10 jours</span> (amœbicide de <span class=\"kw-def\">contact</span>)</li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Forme fulminante</span> mortelle <span class=\"kw-chiffre\">50 %</span>, <span class=\"kw-alerte\">amœbome</span>, <span class=\"kw-alerte\">colite nécrosante aiguë</span></li></ul>"},{"id":"t-amibe-hep","kind":"terminal","label":"Amœbose hépatique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre élevée</span>, <span class=\"kw-clinique\">frissons</span></li><li><span class=\"kw-clinique\">Douleur de l’hypochondre droit</span> irradiant à l’épaule droite</li><li><span class=\"kw-clinique\">Hépatomégalie douloureuse</span> ; <span class=\"kw-clinique\">toux sèche</span> possible</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Sérologie</span> anti-amibiens fortement positive ; <span class=\"kw-alerte\">faux négatif</span> possible la <span class=\"kw-chiffre\">1ʳᵉ semaine</span></li><li><span class=\"kw-bio\">EPS</span> le plus souvent négatif</li><li><span class=\"kw-imagerie\">Échographie</span> : <span class=\"kw-clinique\">abcès</span> unique souvent volumineux ; <span class=\"kw-imagerie\">TDM</span> si <span class=\"kw-clinique\">abcès</span> du dôme</li><li><span class=\"kw-ttt\">Ponction</span> : <span class=\"kw-imagerie\">pus brun chocolat</span>, <span class=\"kw-bio\">PCR</span> sur liquide confirme le diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> puis <span class=\"kw-ttt\">paromomycine</span> (anti-rechute)</li><li>Alternatives : <span class=\"kw-ttt\">tinidazole</span>, <span class=\"kw-ttt\">secnidazole</span></li><li><span class=\"kw-ttt\">Ponction</span> si <span class=\"kw-clinique\">abcès</span> <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique, <span class=\"kw-alerte\">à risque de rupture</span>, échec ou doute diagnostique</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Sous traitement : <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>, baisse rapide de la <span class=\"kw-bio\">CRP</span></li><li><span class=\"kw-imagerie\">Échographie</span> de contrôle seulement si <span class=\"kw-clinique\">évolution</span> défavorable</li></ul>"},{"id":"t-giardiose","kind":"terminal","label":"Giardiose","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Diarrhée</span> chronique fluctuante, sans glaire ni sang ; <span class=\"kw-clinique\">selles malodorantes et décolorées</span></li><li><span class=\"kw-clinique\">Dyspepsie</span> (douleurs ép<span class=\"kw-chiffre\">iga</span>striques, <span class=\"kw-clinique\">nausées</span>, ballonnement) ; <span class=\"kw-clinique\">pas de fièvre</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">enfant</span>, <span class=\"kw-etio\">immunodéprimé</span> ; risque de <span class=\"kw-alerte\">malabsorption</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> (peu sensible) ; <span class=\"kw-bio\">PCR Giardia duodenalis</span> bien plus sensible</li><li><span class=\"kw-bio\">Biopsies</span> jéjunales ou liquide duodénal (formes végétatives)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">5 jours</span> (alternative <span class=\"kw-ttt\">albendazole</span> <span class=\"kw-chiffre\">4 jours</span>)</li><li>Retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités d’enfants)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste</li></ul>"},{"id":"t-crypto","kind":"terminal","label":"Cryptosporidiose","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Diarrhée aiguë cholériforme</span> ou <span class=\"kw-clinique\">diarrhée chronique</span></li><li>Chez l’<span class=\"kw-etio\">immunodéprimé</span> (<span class=\"kw-etio\">VIH</span>) : <span class=\"kw-alerte\">malabsorption</span>, <span class=\"kw-alerte\">angiocholites</span></li></ul><h4>Paraclinique</h4><ul><li>Demande spécifique : <span class=\"kw-bio\">PCR</span> spécifique ou recherche d’<span class=\"kw-etio\">oocystes</span> par coloration de <span class=\"kw-bio\">Ziehl-Nielsen</span></li></ul><h4>Conduite</h4><ul><li>Renforcement des mesures d’<span class=\"kw-clinique\">hygiène</span> ; rechercher une <span class=\"kw-etio\">immunodépression</span> sous-jacente</li></ul>"},{"id":"q-helm","kind":"decision","label":"Helminthe — signe d’appel ?","branches":[{"to":"t-oxyure","label":"Prurit anal vespéral, enfant en collectivité","color":"green"},{"to":"t-taenia","label":"Anneaux « tagliatelles » dans les selles, viande crue","color":"green"},{"to":"t-anguillulose","label":"Larva currens / bilan avant immunosuppression","color":"red"},{"to":"t-ascaris","label":"Syndrome de Löffler + troubles digestifs","color":"green"}]},{"id":"t-oxyure","kind":"terminal","label":"Oxyurose","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Prurit anal vespéral</span> (ponte du ver femelle au coucher)</li><li><span class=\"kw-clinique\">Vulvo-vaginite</span> chez la fille ; <span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">irritabilité</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">enfant en collectivité</span>, cas groupés</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Scotch test</span> le matin avant la toilette ; <span class=\"kw-bio\">EPS</span> souvent négatif</li><li><span class=\"kw-clinique\">Vers adultes</span> visibles à l’œil nu sur la marge anale</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> — traitement toujours indiqué</li><li>Traiter aussi <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span> ; mesures d’hygiène (ongles courts, linge)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Deuxième cure systématique à <span class=\"kw-chiffre\">2 semaines</span> ; contrôle <span class=\"kw-bio\">EPS</span> à distance</li></ul>"},{"id":"t-taenia","kind":"terminal","label":"Taeniasis","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span> ; <span class=\"kw-clinique\">troubles digestifs</span> non spécifiques ; <span class=\"kw-clinique\">urticaire</span></li><li>Émission d’<span class=\"kw-clinique\">anneaux</span> plats blanchâtres (aspect de tagliatelles) dans <span class=\"kw-clinique\">les</span> selles, le linge</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> sur <span class=\"kw-chiffre\">10 jours</span> + <span class=\"kw-bio\">Scotch test</span> (œufs, anneaux, embryophores)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Praziquantel</span> PO, parfois en plusieurs cures</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Vérifier l’absence d’émission d’<span class=\"kw-clinique\">anneaux</span> pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivants</li></ul><h4>Complications</h4><ul><li><span class=\"kw-etio\">Taenia solium</span> → <span class=\"kw-alerte\">cysticercose</span> : neuro (<span class=\"kw-alerte\">crises convulsives</span>, <span class=\"kw-alerte\">HTIC</span>), œil (<span class=\"kw-alerte\">cécité</span>), muscles</li><li>Traitement : <span class=\"kw-ttt\">corticothérapie</span> puis <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">praziquantel</span> en dose unique</li></ul>"},{"id":"t-anguillulose","kind":"terminal","label":"Anguillulose","color":"red","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Larva currens</span> cutanée (<span class=\"kw-clinique\">urticaire</span> + dermatite rampante) ; <span class=\"kw-clinique\">troubles digestifs</span> ; <span class=\"kw-alerte\">syndrome de Löffler</span></li><li><span class=\"kw-alerte\">Anguillulose maligne</span> de l’<span class=\"kw-etio\">immunodéprimé</span> : <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">purpura péri-ombilical</span>, souvent mortelle</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie</span> oscillante, inconstante</li><li>Demande spécifique : technique de <span class=\"kw-bio\">Baermann</span> (larves dans <span class=\"kw-clinique\">les</span> selles) + <span class=\"kw-bio\">sérologie</span> spécifique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span></li></ul><h4>Conduite</h4><ul><li>Dépister et traiter <strong>avant toute immunosuppression</strong> (<span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">chimiothérapie</span>) chez tout patient ayant séjourné en <span class=\"kw-etio\">zone d’endémie</span>, même sans documentation</li></ul>"},{"id":"t-ascaris","kind":"terminal","label":"Ascaridiose","color":"green","detail":"<h4>Clinique</h4><ul><li>Phase d’invasion : <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-alerte\">syndrome de Löffler</span> (fébricule, <span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-imagerie\">infiltrats pulmonaires labiles</span>)</li><li>Phase d’état : <span class=\"kw-clinique\">troubles digestifs</span> non spécifiques ; <span class=\"kw-clinique\">vers adultes</span> parfois excrétés par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span></li></ul><h4>Paraclinique</h4><ul><li>Œufs à l’<span class=\"kw-bio\">EPS</span> en phase d’état (absents en phase d’invasion) ; <span class=\"kw-bio\">PCR</span> en laboratoire spécialisé</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> PO</li></ul>"}]},"cards":[{"i":"2badfbf64bfa","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quel est le principal discriminant biologique permettant de différencier une parasitose à protozoaire d'une helminthiase ?","a":"<p>Le principal discriminant biologique est l'<strong>hyperéosinophilie sanguine</strong>. Elle est toujours <strong>absente</strong> dans les parasitoses à protozoaires, et <strong>possible</strong> dans les helminthiases.</p>"},{"i":"437b3b43fca4","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quelle est la définition des parasitoses digestives selon la classification des agents pathogènes ?","a":"<p>Les parasitoses digestives sont des infections du tube digestif causées soit par des <strong>protozoaires</strong> (parasites unicellulaires), soit par des <strong>helminthes</strong> (vers).</p>"},{"i":"4b159bea7968","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quelles sont les trois parasitoses intestinales les plus fréquentes et se transmettant couramment en France métropolitaine ?","a":"<p>Les trois parasitoses intestinales se transmettant couramment en France métropolitaine sont la <strong>giardiose</strong> (due à <em>Giardia duodenalis</em>), l'<strong>oxyurose</strong> (due à <em>Enterobius vermicularis</em>) et le <strong>taeniasis à <em>Taenia saginata</em></strong>.</p>"},{"i":"1d77997ebc0c","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quels sont les méthodes diagnostiques spécifiques de la giardiose ?","a":"<p>Pour la giardiose, le diagnostic peut être confirmé par :</p><ul><li>Un <strong>EPS</strong> (recherche de formes végétatives ou kystiques), bien que peu sensible.</li><li>Une <strong>PCR <em>Giardia duodenalis</em></strong>, beaucoup plus sensible.</li><li>Plus rarement, des <strong>biopsies jéjunales</strong> ou l'analyse du <strong>liquide duodénal</strong>.</li></ul>"},{"i":"4db027f6100f","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quel est l'examen de base pour diagnostiquer les parasitoses intestinales et comment doit-il être réalisé ?","a":"<p>L'examen de base est l'<strong>EPS (examen parasitologique des selles)</strong>. Pour une sensibilité optimale, il doit être réalisé <strong>3 fois</strong> à quelques jours d'intervalle, avec un <strong>acheminement rapide</strong> au laboratoire en raison de la fragilité des parasites.</p>"},{"i":"74c91d07b386","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quelles sont les méthodes de confirmation diagnostique de l'anguillulose et de la cryptosporidiose ?","a":"<p>Pour l'anguillulose, le diagnostic repose sur la <strong>technique de Baermann</strong> (recherche des larves) et une <strong>sérologie spécifique</strong>.</p><p>Pour la cryptosporidiose, le diagnostic est confirmé par une <strong>PCR spécifique</strong> ou une <strong>coloration de Ziehl-Nielsen</strong> sur les selles.</p>"},{"i":"74e160022884","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quels sont les examens complémentaires pour confirmer une oxyurose ?","a":"<p>Le diagnostic de l'oxyurose est principalement basé sur le <strong>Scotch test</strong> (cellophane adhésive appliquée le matin avant la toilette anale puis examinée au microscope). Un <strong>EPS</strong> est souvent négatif pour l'oxyurose. Des <strong>vers adultes</strong> peuvent être visibles à l'œil nu.</p>"},{"i":"bfd30aeaa1e4","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Comment est diagnostiquée l'ascaridiose ?","a":"<p>Pour l'ascaridiose, le diagnostic repose sur :</p><ul><li>La mise en évidence d'<strong>œufs à l'EPS</strong> durant la phase d'état.</li><li>Le <strong>rejet de vers adultes</strong>.</li></ul><p>Il est important de noter qu'à la phase d'invasion, les œufs ne sont pas encore éliminés dans les selles et l'EPS peut être négatif.</p>"},{"i":"d6b8cb863749","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Comment diagnostique-t-on un Tæniasis ?","a":"<p>Le diagnostic d'un Tæniasis repose sur :</p><ul><li>Un <strong>EPS ×3 sur 10 jours</strong>, recherchant les œufs, anneaux ou embryophores microscopiques.</li><li>Un <strong>Scotch test</strong>, qui peut également révéler des anneaux ou des embryophores de Tænia (mais n'est pas spécifique de l'oxyurose).</li></ul>"},{"i":"4a47a26a7933","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"Quelle est la différence macroscopique notable entre l'émission d'anneaux de <i>Taenia saginata</i> et de <i>Taenia solium</i> ?","a":"<p>La différence réside dans le mode d'émission des anneaux :</p><ul><li>Pour <i>Taenia saginata</i> : les anneaux sont émis <strong>activement</strong> par l'anus.</li><li>Pour <i>Taenia solium</i> : les anneaux sont émis <strong>passivement</strong>.</li></ul>"},{"i":"7e2c8f18fc30","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"À quel embranchement et quelle classe de parasites les Taenia appartiennent-ils ?","a":"<p>Les Taenia appartiennent à l'embranchement des <strong>cestodes</strong>, qui sont des <strong>vers plats segmentés</strong>.</p>"},{"i":"a8c11d9195cd","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"Comment les Taenia se présentent-ils macroscopiquement dans les selles ou les sous-vêtements ?","a":"<p>Les Taenia se présentent sous forme d'<strong>anneaux plats blanchâtres</strong>, décrits comme ayant l'aspect de « <strong>petites tagliatelles</strong> ».</p>"},{"i":"afaa5a58b97a","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention de l'ascaridiose ?","a":"<p>Le traitement de première intention de l'ascaridiose repose sur l'<strong>albendazole</strong> ou le <strong>flubendazole</strong> par voie orale.</p>"},{"i":"b7827b1819f3","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention de la giardiose et ses particularités ?","a":"<p>Le traitement de première intention de la giardiose repose sur le <strong>métronidazole</strong> par voie orale pendant <strong>5 jours</strong>. Une alternative est l'<strong>albendazole</strong> pendant 4 jours. Un retraitement à 15 jours est parfois recommandé en collectivité, et un contrôle parasitologique des selles doit être réalisé à distance si la diarrhée persiste.</p>"},{"i":"d4b42d632550","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention du tæniasis ?","a":"<p>Le traitement de première intention du tæniasis est le <strong>praziquantel</strong> par voie orale, parfois répété en plusieurs cures.</p>"},{"i":"f11d028a6590","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Comment doit être traitée l'oxyurose et quelles sont les mesures associées ?","a":"<p>Le traitement de l'oxyurose repose sur l'<strong>albendazole</strong> ou le <strong>flubendazole</strong>. Le traitement est toujours indiqué et doit inclure les sujets contacts. Une <strong>deuxième cure systématique</strong> est impérative <strong>2 semaines</strong> plus tard pour interrompre le cycle d'auto-infestation. Des mesures d'hygiène associées sont essentielles : avoir les ongles courts, brossage des ongles et changement de tout le linge de corps et de lit.</p>"},{"i":"290eefc82a21","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Dans quel contexte épidémiologique l'amœbose hépatique est-elle la plus fréquente en France ?","a":"<p>En France, l'amœbose hépatique est une pathologie qui touche principalement les <strong>voyageurs</strong> ou les <strong>migrants</strong>. Sa répartition géographique est liée aux <strong>pays d'endémie de la ceinture intertropicale</strong>.</p>"},{"i":"7a129f9a1f58","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quel est l'agent pathogène responsable de l'échinococcose hydatique et quelle est sa particularité chez l'homme ?","a":"<p>L'agent pathogène est <strong><em>Echinococcus granulosus</em></strong>, un tænia du chien. Chez l'homme, il s'agit d'une <strong>impasse parasitaire</strong>, l'homme étant un hôte intermédiaire accidentel.</p>"},{"i":"e35b4a8069b9","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quelle est la physiopathologie de l'amœbose hépatique ?","a":"<p>L'amœbose hépatique survient toujours à la suite d'une <strong>atteinte intestinale</strong>. Les trophozoïtes d'<em>Entamoeba histolytica</em> disséminent par la <strong>veine porte</strong> jusqu'au foie, où ils peuvent former un abcès.</p>"},{"i":"ebe32c4e7a92","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quels sont les deux principaux agents pathogènes responsables de parasitoses digestives pouvant entraîner une atteinte hépatique ?","a":"<p>Les deux principaux agents pathogènes sont :</p><ul><li><strong><em>Entamoeba histolytica</em></strong> pour l'amœbose hépatique.</li><li><strong><em>Echinococcus granulosus</em></strong> pour l'échinococcose hydatique.</li></ul>"},{"i":"08f0fd93ae52","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quels sont les modes de transmission spécifiques de la giardiose, de l'amœbose et de la cryptosporidiose ?","a":"<ul><li><strong>Giardiose</strong> : Transmission <strong>indirecte</strong> (eau, aliments) ou <strong>directe</strong> (mains souillées), avec une transmission interhumaine et horizontale.</li><li><strong>Amœbose</strong> : Transmission par la <strong>voie orofécale</strong> (eau, aliments) ou par <strong>manuportage</strong>, via les formes kystiques présentes dans le milieu extérieur.</li><li><strong>Cryptosporidiose</strong> : Transmission <strong>indirecte</strong> (eau, aliments) ou <strong>directe</strong> (mains souillées).</li></ul>"},{"i":"8f5e9908c6cd","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quel est le mode de transmission principal des parasitoses digestives en général ?","a":"<p>Le mode de transmission principal des parasitoses digestives est le <strong>péril fécal</strong>, c'est-à-dire la <strong>transmission féco-orale</strong>.</p>"},{"i":"95b22bc7f084","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quelle parasitose digestive parmi celles listées se distingue par un mode de contamination non féco-oral ?","a":"<p>L'<strong>anguillulose</strong> est la seule parasitose digestive de cette liste à ne pas suivre la voie féco-orale, sa contamination étant <strong>transcutanée</strong>.</p>"},{"i":"b184587f54f0","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Comment s'effectue la transmission du taeniasis et de l'oxyurose ?","a":"<ul><li><strong>Taeniasis</strong> : Ingestion de <strong>viande parasitée mal cuite ou crue</strong> (bœuf pour <em>T. saginata</em>, porc pour <em>T. solium</em>).</li><li><strong>Oxyurose</strong> : Ingestion d'œufs (via les mains, sous-vêtements, literie), avec une <strong>auto-infestation orale fréquente</strong> après grattage anal.</li></ul>"},{"i":"dc1ed7063220","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quel est le mode de transmission de l'ascaridiose et de l'anguillulose ?","a":"<ul><li><strong>Ascaridiose</strong> : Ingestion d'œufs présents dans l'eau ou les aliments souillés, liée au <strong>péril fécal humain</strong>.</li><li><strong>Anguillulose</strong> : <strong>Pénétration transcutanée des larves</strong>, principalement lors de la marche pieds nus sur une terre humide.</li></ul>"},{"i":"0b77e0aa18d0","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Comment se manifeste cliniquement une oxyurose ?","a":"<p>L'oxyurose est le plus souvent <strong>asymptomatique</strong>. La manifestation clinique principale est le <strong>prurit anal vespéral</strong>, lié à la ponte du ver femelle au coucher.</p><p>Chez la fille, une <strong>vulvo-vaginite</strong> est possible. Des troubles comportementaux tels que l'irritabilité, les troubles de la concentration ou du sommeil peuvent parfois être la seule manifestation.</p>"},{"i":"21560f77d905","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Comment se manifeste cliniquement la cryptosporidiose ?","a":"<p>La cryptosporidiose se manifeste principalement par une <strong>diarrhée aiguë cholériforme</strong> ou une <strong>diarrhée chronique</strong>.</p>"},{"i":"25b45daebd51","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelle est la présentation clinique de l'anguillulose ?","a":"<p>L'anguillulose est le plus souvent <strong>asymptomatique</strong>. Les manifestations cliniques peuvent inclure :</p><ul><li>Une <strong>larva currens cutanée</strong>.</li><li>Des troubles digestifs.</li><li>Un <strong>syndrome de Löffler</strong>.</li></ul>"},{"i":"61d11580c975","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques de l'ascaridiose ?","a":"<p>L'ascaridiose peut se manifester en deux phases :</p><ul><li>La <strong>phase d'invasion</strong> est souvent asymptomatique, mais il peut y avoir une urticaire, et parfois un <strong>syndrome de Löffler</strong>.</li><li>La <strong>phase d'état</strong> est également souvent asymptomatique ou se manifeste par des troubles digestifs non spécifiques (dyspepsie, nausées).</li><li>Une particularité est l'excrétion des vers adultes par les <strong>vomissements</strong> ou les selles.</li></ul>"},{"i":"707959e3efb3","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques d'un taeniasis ?","a":"<p>Le taeniasis est le plus souvent <strong>asymptomatique</strong>. Des manifestations non spécifiques peuvent inclure :</p><ul><li>Des troubles digestifs : douleurs abdominales, nausées, troubles de l'appétit.</li><li>Des manifestations cutanées : urticaire.</li><li>Le signe d'appel caractéristique est l'<strong>émission d'anneaux</strong> (proglottis) dans les selles, les sous-vêtements ou la literie.</li></ul>"},{"i":"b6e7050cc7b7","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques possibles de la giardiose ?","a":"<p>La giardiose est souvent <strong>asymptomatique</strong>. En cas de symptômes, elle peut provoquer :</p><ul><li>Une <strong>dyspepsie</strong> : douleurs épigastriques, nausées, ballonnement post-prandial.</li><li>Une <strong>diarrhée chronique</strong>, fluctuante, sans glaire ni sang, avec des selles malodorantes et décolorées.</li><li>La fièvre est généralement absente.</li><li>Elle peut être associée à la <strong>malnutrition infantile</strong> dans les pays en développement.</li></ul>"},{"i":"2c8571354752","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quelles sont les manifestations cliniques de l'amœbose intestinale aiguë non compliquée ?","a":"<p>L'amœbose intestinale aiguë se manifeste par :</p><ul><li>Un <strong>syndrome dysentérique</strong> (surtout chez l'enfant en pays tropical).</li><li>Des <strong>douleurs abdominales</strong>.</li><li>Des selles molles peu nombreuses, avec une perte de la selle moulée quotidienne.</li><li>Des signes rectaux : <strong>épreintes</strong>, <strong>ténesme</strong>, et toucher rectal douloureux.</li><li>La <strong>fièvre est ABSENTE</strong>, ce qui est un signe négatif capital.</li></ul>"},{"i":"b42668e75947","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quels sont les signes cliniques de l'amœbose hépatique (abcès amibien) ?","a":"<p>L'amœbose hépatique se caractérise par :</p><ul><li>Des signes généraux : <strong>fièvre élevée</strong> et <strong>frissons</strong>.</li><li>Une douleur de l'<strong>hypochondre droit</strong>, irradiant à l'épaule droite.</li><li>À l'examen : une <strong>hépatomégalie douloureuse</strong> à la palpation.</li><li>Des signes respiratoires : une <strong>toux sèche</strong> possible (par irritation phrénique).</li></ul>"},{"i":"bcb881b38a93","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quel est le piège diagnostique classique concernant la fièvre dans l'amœbose ?","a":"<p>Le piège classique est que l'<strong>amœbose hépatique</strong> peut s'accompagner de <strong>diarrhées fébriles</strong>, tandis que l'<strong>amœbose intestinale aiguë n'est JAMAIS fébrile</strong>.</p>"}]};